local function s(v) if type(v) == "table" and v.value ~= nil then return tostring(v.value) end if type(v) == "table" then local t = {} for i, x in ipairs(v) do t[i] = s(x) end return "{" .. table.concat(t, ", ") .. "}" end if type(v) == "userdata" then local ok, r = pcall(function() return v.value end) if ok and r ~= nil and r ~= "" then return tostring(r) end end return tostring(v) end local function f(p) local ok, v = pcall(function() return TweakDB:GetFlat(p) end) if ok and v ~= nil then return s(v) end return "nil" end local function P(x) print("[SDPT] " .. x) end local function ids(ty) local out = {} local ok, rr = pcall(function() return TweakDB:GetRecords(ty) end) if ok and rr then for _, r in ipairs(rr) do local okI, id = pcall(function() return r:GetID().value end) if okI and id then table.insert(out, id) end end end return out end local modes = {} for _, id in ipairs(ids("gamedataAIActionTarget_Record")) do local m = f(id .. ".trackingMode") modes[m] = (modes[m] or 0) + 1 if m:find("Real") or m:find("Belief") then P("target " .. id .. " trackingMode=" .. m) end end for m, n in pairs(modes) do P("trackingMode " .. m .. ": " .. n .. " targets") end for _, id in ipairs(ids("gamedataThreatTrackingPresetBase_Record")) do P("preset " .. id .. " baseAcc=" .. f(id .. ".baseAccuracy") .. " beliefAcc=" .. f(id .. ".beliefAccuracy") .. " visBeliefSpeed=" .. f(id .. ".visibleBeliefSpeedMultiplier") .. " moveBeliefOnlyIfVisible=" .. f(id .. ".moveBeliefOnlyIfVisible") .. " dropCd=" .. f(id .. ".baseDroppingThreatCooldown") .. " dropPerSecVisible=" .. f(id .. ".droppingCooldownPerSecondWhileVisible") .. " dropPerHit=" .. f(id .. ".droppingCooldownPerHit") .. " dropMax=" .. f(id .. ".maximumDroppingCooldownValue")) end local n, sum, buckets = 0, 0, {0, 0, 0, 0, 0, 0, 0} local edges = {0, 0.1, 0.25, 0.5, 1, 2, 5} for _, id in ipairs(ids("gamedataAIPatternDelay_Record")) do local okD, d = pcall(function() return TweakDB:GetFlat(id .. ".delay") end) if okD and type(d) == "number" and d < 100 then n = n + 1 sum = sum + d local b = 1 for i = #edges, 1, -1 do if d >= edges[i] then b = i break end end buckets[b] = buckets[b] + 1 end end P(("patternDelay <100s: n=%d mean=%.3f | 0-0.1:%d 0.1-0.25:%d 0.25-0.5:%d 0.5-1:%d 1-2:%d 2-5:%d 5+:%d"):format(n, n > 0 and sum / n or 0, buckets[1], buckets[2], buckets[3], buckets[4], buckets[5], buckets[6], buckets[7])) P("done")
